package com.cowave.search.inbound_adapter.legacy.listener

import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ProductCdcEnvelope
import com.cowave.search.application.index.mapper.LegacySyncMapper
import com.cowave.search.application.index.service.LegacyReserveSyncApplicationService
import com.cowave.search.domain.index.policy.ProductMergeStrategy
import com.cowave.search.inbound_adapter.legacy.mapper.toChangedProductData
import com.cowave.shared.utils.logger
import org.apache.avro.specific.SpecificRecord
import org.apache.kafka.clients.consumer.Consumer
import org.apache.kafka.clients.consumer.ConsumerRecord
import org.springframework.kafka.listener.BatchAcknowledgingConsumerAwareMessageListener
import org.springframework.kafka.support.Acknowledgment

class LegacyReserveSyncListener(
    private val legacyReserveSyncApplicationService: LegacyReserveSyncApplicationService,
) : BatchAcknowledgingConsumerAwareMessageListener<SpecificRecord, SpecificRecord> {
    private val logger by logger()

    override fun onMessage(
        data: List<ConsumerRecord<SpecificRecord, SpecificRecord>>,
        acknowledgment: Acknowledgment?,
        consumer: Consumer<*, *>,
    ) {
        runCatching {
            val changedDocuments =
                data
                    .mapNotNull { record ->
                        val envelope = record.value() as ProductCdcEnvelope
                        val product = envelope.after ?: envelope.before
                        if (product != null && product.categoryId > 0) {
                            record.toChangedProductData()
                        } else {
                            null
                        }
                    }
            val mergedDocuments = ProductMergeStrategy.merge(changedDocuments)
            legacyReserveSyncApplicationService.syncToLegacy(LegacySyncMapper.convertToChangedLegacyData(mergedDocuments))
        }.onSuccess {
            acknowledgment?.acknowledge()
        }.onFailure { ex ->
            logger.error(ex) { "Failed to sync products to legacy" }
        }.getOrThrow()
    }
}

package com.cowave.search.inbound_adapter.legacy.config

import com.cowave.search.application.index.service.LegacyReserveSyncApplicationService
import com.cowave.search.inbound_adapter.legacy.listener.LegacyReserveSyncListener
import org.apache.avro.specific.SpecificRecord
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.kafka.listener.ConcurrentMessageListenerContainer

@Configuration
@ConditionalOnProperty(name = ["legacy-sync.enabled"], havingValue = "true")
class LegacyReserveSyncKafkaConfig(
    private val legacyReserveSyncConsumerProperties: LegacyReserveSyncConsumerProperties,
    private val legacyReserveSyncApplicationService: LegacyReserveSyncApplicationService,
) {
    @Bean
    fun legacyReserveSyncKafkaListenerContainer(): ConcurrentMessageListenerContainer<SpecificRecord, SpecificRecord> {
        val listener =
            LegacyReserveSyncListener(
                legacyReserveSyncApplicationService = legacyReserveSyncApplicationService,
            )
        return LegacyReserveSyncContainerFactory.createCdcContainer(
            dynamicIndexConsumer = legacyReserveSyncConsumerProperties.productCdc,
            listener = listener,
        )
    }
}

package com.cowave.search.inbound_adapter.legacy.config

import io.confluent.kafka.serializers.KafkaAvroDeserializer
import org.apache.avro.specific.SpecificRecord
import org.apache.kafka.clients.consumer.ConsumerConfig
import org.apache.kafka.common.IsolationLevel
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory
import org.springframework.kafka.core.DefaultKafkaConsumerFactory
import org.springframework.kafka.listener.BatchAcknowledgingConsumerAwareMessageListener
import org.springframework.kafka.listener.ConcurrentMessageListenerContainer
import org.springframework.kafka.listener.ContainerProperties
import org.springframework.kafka.listener.DefaultErrorHandler
import org.springframework.util.backoff.FixedBackOff
import org.springframework.util.backoff.FixedBackOff.UNLIMITED_ATTEMPTS

object LegacyReserveSyncContainerFactory {
    fun createCdcContainer(
        dynamicIndexConsumer: LegacyReserveSyncConsumerProperties.DynamicIndexConsumer,
        listener: BatchAcknowledgingConsumerAwareMessageListener<SpecificRecord, SpecificRecord>,
    ): ConcurrentMessageListenerContainer<SpecificRecord, SpecificRecord> {
        val containerFactory =
            ConcurrentKafkaListenerContainerFactory<SpecificRecord, SpecificRecord>().apply {
                setConcurrency(dynamicIndexConsumer.concurrency)
                isBatchListener = true
                containerProperties.ackMode = ContainerProperties.AckMode.MANUAL_IMMEDIATE
                containerProperties.groupId = dynamicIndexConsumer.groupId
                containerProperties.idleEventInterval = dynamicIndexConsumer.idleEventInterval
                consumerFactory =
                    DefaultKafkaConsumerFactory(
                        getKafkaConsumerProperties(dynamicIndexConsumer),
                        KafkaAvroDeserializer(),
                        KafkaAvroDeserializer(),
                    )
                setCommonErrorHandler(getDefaultErrorHandler())
            }

        return containerFactory.createContainer(dynamicIndexConsumer.topic).apply {
            setupMessageListener(listener)
        }
    }

    private fun getKafkaConsumerProperties(dynamicIndexConsumer: LegacyReserveSyncConsumerProperties.DynamicIndexConsumer): Map<String, Any> =
        mutableMapOf(
            ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG to dynamicIndexConsumer.bootstrapServers,
            ConsumerConfig.ISOLATION_LEVEL_CONFIG to IsolationLevel.READ_COMMITTED.toString().lowercase(),
            ConsumerConfig.AUTO_OFFSET_RESET_CONFIG to dynamicIndexConsumer.properties.autoOffsetReset,
            ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG to dynamicIndexConsumer.properties.enableAutoCommit,
            ConsumerConfig.MAX_POLL_RECORDS_CONFIG to dynamicIndexConsumer.properties.maxPollRecords,
            ConsumerConfig.FETCH_MAX_WAIT_MS_CONFIG to dynamicIndexConsumer.properties.fetchMaxWaitMs,
            ConsumerConfig.FETCH_MIN_BYTES_CONFIG to dynamicIndexConsumer.properties.fetchMinSize,
//            "spring.json.trusted.packages" to "*",
//            "spring.json.use.type.headers" to false,
        ).apply {
            dynamicIndexConsumer.properties.schemaRegistryUrl?.let { put("schema.registry.url", it) }
            dynamicIndexConsumer.properties.specificAvroReader?.let { put("specific.avro.reader", it) }
            dynamicIndexConsumer.properties.securityProtocol?.let { put("security.protocol", it) }
            dynamicIndexConsumer.properties.saslMechanism?.let { put("sasl.mechanism", it) }
            dynamicIndexConsumer.properties.saslJaasConfig?.let { put("sasl.jaas.config", it) }
        }.toMap()

    private fun getDefaultErrorHandler(): DefaultErrorHandler =
        DefaultErrorHandler(
            { _, _ -> },
            FixedBackOff(1000L, UNLIMITED_ATTEMPTS),
        ).apply {
            isAckAfterHandle = false
        }
}

