import com.cowave.search.application.index.dto.Dependency
import com.cowave.search.application.index.dto.DependencyId
import org.springframework.beans.factory.annotation.Qualifier
import org.springframework.stereotype.Service
import java.util.concurrent.CompletableFuture
import java.util.concurrent.Executor

@Service
class CachedProxyApplicationService(
    private val categoryApplicationService: CategoryApplicationService,
    private val brandApplicationService: BrandApplicationService,
    private val manufacturerApplicationService: ManufacturerApplicationService,
    private val mallApplicationService: MallApplicationService,
    @param:Qualifier("IOExecutor") private val ioExecutor: Executor,
) {
    fun fetchDependencies(dependencyId: DependencyId): Dependency {
        val categoryFuture = async(dependencyId.categoryIds, categoryApplicationService::getCachedAllByIds)
        val brandFuture = async(dependencyId.brandIds, brandApplicationService::getCachedAllByIds)
        val manufacturerFuture = async(dependencyId.manufacturerIds, manufacturerApplicationService::getCachedAllByIds)
        val mallFuture = async(dependencyId.mallIds, mallApplicationService::getCachedAllByIds)
        CompletableFuture.allOf(categoryFuture, brandFuture, manufacturerFuture, mallFuture).join()

        return Dependency(
            categories = categoryFuture.join(),
            brands = brandFuture.join(),
            manufacturers = manufacturerFuture.join(),
            malls = mallFuture.join(),
        )
    }

    private fun <K, V> async(
        ids: List<K>,
        fetch: (List<K>) -> Map<K, V>,
    ): CompletableFuture<Map<K, V>> =
        if (ids.isEmpty()) {
            CompletableFuture.completedFuture(emptyMap())
        } else {
            CompletableFuture.supplyAsync({ fetch(ids) }, ioExecutor)
        }
}

